import JSZip from 'jszip';
import { DocItem, DownloadMetrics } from '../types';
import { generateValidPdfBytes } from './pdfGenerator';

export interface ZipProgressInfo {
  percent: number;
  currentFileName: string;
  currentFileIndex: number;
  totalFiles: number;
  state: 'preparing' | 'compressing' | 'generating' | 'completed' | 'cancelled';
}

/**
 * Downloads a single PDF file directly from GitHub Raw CDN or generated bytes
 * Enforces a strict 20 MB hard limit on individual egress.
 */
export async function downloadSinglePdf(item: DocItem, maxBytes: number = 20 * 1024 * 1024): Promise<void> {
  // Enforce 20 MB hard limit on individual download egress
  if (item.size && item.size > maxBytes) {
    throw new Error(`Download blocked: ${item.name} exceeds the 20 MB egress limit (${(item.size / (1024 * 1024)).toFixed(1)} MB).`);
  }

  // If item has a direct download / raw CDN URL, trigger native browser fetch & download
  if (item.downloadUrl) {
    try {
      const resp = await fetch(item.downloadUrl, { mode: 'cors' });
      if (resp.ok) {
        const blob = await resp.blob();
        if (blob.size > maxBytes) {
          throw new Error(`Download blocked: Payload exceeds 20 MB limit (${(blob.size / (1024 * 1024)).toFixed(1)} MB).`);
        }
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = item.name;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        setTimeout(() => URL.revokeObjectURL(url), 1000);
        return;
      }
    } catch (e: unknown) {
      if (e instanceof Error && e.message.includes('Download blocked')) {
        throw e;
      }
      // If CORS or network fetch issue, fallback to direct anchor or generator
    }
  }

  // Fallback to generator
  const rawBytes = item.contentGenerator
    ? await Promise.resolve(item.contentGenerator())
    : generateValidPdfBytes({
        title: item.name.replace(/\.pdf$/i, ''),
        category: item.category || 'B.Tech Paper',
        summary: item.summary,
      });

  if (rawBytes.byteLength > maxBytes) {
    throw new Error(`Download blocked: Generated payload exceeds 20 MB egress limit (${(rawBytes.byteLength / (1024 * 1024)).toFixed(1)} MB).`);
  }

  const blob = new Blob([rawBytes as unknown as BlobPart], { type: 'application/pdf' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = item.name;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/**
 * Compresses up to 30 PDF files client-side into a ZIP archive with real-time progress callbacks.
 */
export async function createAndDownloadZip(
  files: DocItem[],
  onProgress?: (progress: ZipProgressInfo) => void,
  signal?: AbortSignal
): Promise<DownloadMetrics> {
  const startTime = performance.now();
  const cappedFiles = files.slice(0, 30);
  const totalFiles = cappedFiles.length;

  if (totalFiles === 0) {
    throw new Error('No files provided for ZIP generation');
  }

  const zip = new JSZip();
  let totalUncompressedBytes = 0;
  const fileNames: string[] = [];

  // Stage 1: Fetch or generate PDF bytes and pack into flat zip
  for (let i = 0; i < totalFiles; i++) {
    if (signal?.aborted) {
      throw new DOMException('Compression cancelled by user', 'AbortError');
    }

    const file = cappedFiles[i];
    fileNames.push(file.name);

    onProgress?.({
      percent: Math.round(((i + 0.2) / totalFiles) * 50),
      currentFileName: file.name,
      currentFileIndex: i + 1,
      totalFiles,
      state: 'preparing',
    });

    // Obtain real PDF bytes from GitHub Raw CDN or generator
    let pdfBytes: Uint8Array;
    if (file.contentGenerator) {
      pdfBytes = await Promise.resolve(file.contentGenerator());
    } else {
      pdfBytes = generateValidPdfBytes({
        title: file.name.replace(/\.pdf$/i, ''),
        category: file.category || 'B.Tech Question Paper',
        summary: file.summary,
      });
    }

    totalUncompressedBytes += pdfBytes.byteLength;

    // Flat archive: only PDF files at the root level, no nested folders
    let targetFileName = file.name;
    let collisionCounter = 1;
    while (zip.file(targetFileName)) {
      const extIdx = file.name.lastIndexOf('.');
      const baseName = extIdx !== -1 ? file.name.substring(0, extIdx) : file.name;
      const ext = extIdx !== -1 ? file.name.substring(extIdx) : '.pdf';
      const disambiguator = file.semester ? ` [${file.semester}]` : file.year ? ` [${file.year}]` : ` (${collisionCounter})`;
      targetFileName = `${baseName}${disambiguator}${collisionCounter > 1 ? `-${collisionCounter}` : ''}${ext}`;
      collisionCounter++;
    }

    zip.file(targetFileName, pdfBytes, { binary: true });

    // Yield to the event loop so UI updates smoothly
    await new Promise((resolve) => setTimeout(resolve, 15));
  }

  // Stage 2: Generate compressed zip blob with progress callback
  onProgress?.({
    percent: 60,
    currentFileName: 'Compressing archive payload...',
    currentFileIndex: totalFiles,
    totalFiles,
    state: 'generating',
  });

  const zipBlob = await zip.generateAsync(
    {
      type: 'blob',
      compression: 'DEFLATE',
      compressionOptions: { level: 6 },
    },
    (metadata) => {
      const compressionPercent = 60 + Math.round(metadata.percent * 0.38);
      onProgress?.({
        percent: Math.min(99, compressionPercent),
        currentFileName: metadata.currentFile ? `Packing ${metadata.currentFile}` : 'Finalizing archive...',
        currentFileIndex: totalFiles,
        totalFiles,
        state: 'generating',
      });
    }
  );

  const durationMs = Math.round(performance.now() - startTime);
  const totalCompressedBytes = zipBlob.size;

  // Format date stamp for filename: YYYYMMDD-HHMM
  const now = new Date();
  const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
  const timeStr = `${String(now.getHours()).padStart(2, '0')}${String(now.getMinutes()).padStart(2, '0')}`;
  const archiveName = `btechpapers-bundle-${dateStr}-${timeStr}.zip`;

  if (signal?.aborted) {
    throw new DOMException('Compression cancelled by user', 'AbortError');
  }

  // Trigger download
  const downloadUrl = URL.createObjectURL(zipBlob);
  const downloadLink = document.createElement('a');
  downloadLink.href = downloadUrl;
  downloadLink.download = archiveName;
  document.body.appendChild(downloadLink);
  downloadLink.click();
  document.body.removeChild(downloadLink);
  URL.revokeObjectURL(downloadUrl);

  const uncompressedMb = (totalUncompressedBytes / (1024 * 1024)).toFixed(2);
  const compressedMb = (totalCompressedBytes / (1024 * 1024)).toFixed(2);
  const ratioPercent =
    totalUncompressedBytes > 0
      ? `${Math.max(0, Math.round((1 - totalCompressedBytes / totalUncompressedBytes) * 100))}%`
      : '0%';

  const speedMBps =
    durationMs > 0
      ? (totalUncompressedBytes / (1024 * 1024) / (durationMs / 1000)).toFixed(1)
      : '0.0';

  onProgress?.({
    percent: 100,
    currentFileName: archiveName,
    currentFileIndex: totalFiles,
    totalFiles,
    state: 'completed',
  });

  return {
    archiveName,
    fileCount: totalFiles,
    fileNames,
    uncompressedBytes: totalUncompressedBytes,
    compressedBytes: totalCompressedBytes,
    uncompressedMb,
    compressedMb,
    compressionRatio: ratioPercent,
    durationMs,
    speedMBps,
  };
}
